  .bar:after{ bottom:0;}
  .dot:before{ content:""; width:18px;height:18px;border-radius:50%;border:2px solid #fff; display:block;}
  .gear:before{
    content:"⚙"; color:#fff; font-size:18px; line-height:18px; display:block; text-align:center;
