  }
  .editor.show{ display:block;}
  .editor input[type=text]{
    width:100%; padding:12px; border-radius:8px; border:1px solid #e6e6e6; font-size:18px;
  }
  .field-title{ margin:12px 0 6px; font-weight:700; color:#333;}
  .step{
    display:flex; align-items:center; gap:8px;
  }
  .step .box{
    width:48px; height:40px; border:1px solid #e1e1e1; border-radius:8px; display:grid; place-items:center;
    background:#f5f5f5; font-weight:700;
  }
  .mini.btn{
    width:36px; height:36px; border-radius:8px; border:1px solid #ddd; background:#fff; cursor:pointer;
    display:grid; place-items:center; box-shadow:0 2px 0 #eee inset;
  }
  .editor .links{
    display:flex; gap:16px; margin:12px 0 10px; color:#666; font-weight:600; font-size:14px;
  }
  .editor .links img{ width:14px; height:14px; opacity:.6; vertical-align:middle; margin-left:4px;}
  .editor .actions{
    display:flex; justify-content:flex-end; align-items:center; gap:18px; margin-top:10px;
  }
  .cancel.btn{ color:#777; font-weight:700; cursor:pointer; }
  .save.btn{
    background:#3b3f44; color:#fff; padding:10px 16px; border-radius:10px; cursor:pointer; font-weight:700;
  }

  /* Tasks */
  .task{
    background:#fff; color:#333; border-radius:10px; padding:12px; display:flex; align-items:center;
    justify-content:space-between; margin:10px 0; position:relative;
    box-shadow:0 5px 12px rgba(0,0,0,.18);
  }
  .task:before{
    content:""; position:absolute; left:0; top:0; bottom:0; width:6px; background:#222; border-radius:10px 0 0 10px;
  }
  .left{
    display:flex; align-items:center; gap:10px; flex:1 1 auto; min-width:0;
  }
  .chk.btn{
    width:22px; height:22px; border:2px solid #999; border-radius:50%; display:inline-block; position:relative;
    background:#fff;
  }
  .chk.done{ background:#8ac79b; border-color:#7bb78e; }
  .chk.done:after{
    content:""; position:absolute; left:5px; top:9px; width:8px; height:4px;
    border-left:3px solid #fff; border-bottom:3px solid #fff; transform:rotate(-45deg);
  }
  .ttext{
    white-space:nowrap; overflow:hidden; text-overflow:ellipsis; font-weight:700;
  }
  .muted{ color:#999; font-weight:700; }
  .kebab.btn{
    width:30px; height:30px; border-radius:8px; background:#f1f1f1; color:#666; display:grid; place-items:center;
  }
  .kebab.btn:before{ content:"⋮"; }

  /* Summary */
  .summary{
    margin-top:14px; background:rgba(255,255,255,.15); border-radius:10px; padding:14px;
    box-shadow:0 8px 16px var(--shadow) inset; font-weight:700;
  }
  .summary strong{ color:#fff; }

  /* Toast */
  .toast{
    position:fixed; left:18px; right:18px; bottom:18px; background:#fff; color:#222;
    border-radius:14px; box-shadow:0 10px 20px rgba(0,0,0,.25); padding:14px; display:none;
    align-items:center; justify-content:space-between; gap:10px; z-index:50;
  }
  .toast.show{ display:flex; }
  .toast .clear.btn{
    background:#3FA773; color:#fff; padding:10px 14px; border-radius:10px; font-weight:800; cursor:pointer;
  }

  /* Confetti canvas */
  #confetti{
    position:fixed; inset:0; pointer-events:none; display:none; z-index:40;
  }

  /* Themes */
  body.short{
    --bg:#7e5b60;
    --panel:#8c686d;
    --muted:#e0c4c7;
  }
  body.long{
    --bg:#2c8c8a;
    --panel:#2f9b98;
    --muted:#b7e3e1;
  }
</style>
</head>
<body>
<canvas id="confetti"></canvas>

<div class="wrap">
  <header class="top">
    <div class="brand">
      <span class="tick" aria-hidden="true"></span>
      <span>Pomofocus</span>
    </div>
    <div class="icons">
      <div class="icon btn" title="Stats"><span class="bar"><i></i></span></div>
      <div class="icon btn" title="Settings"><span class="gear"></span></div>
      <div class="icon btn" title="Account"><span class="dot"></span></div>
      <div class="icon btn" title="More"><span class="meat"></span></div>
    </div>
  </header>

  <section class="card" id="timerCard">
    <div class="tabs">
      <div class="tab btn active" data-mode="pomodoro">Pomodoro</div>
      <div class="tab btn" data-mode="short">Short Break</div>
      <div class="tab btn" data-mode="long">Long Break</div>
    </div>
    <div class="display" id="time">25:00</div>
    <div class="controls">
      <button class="main-btn btn" id="startBtn">START</button>
    </div>
    <div class="subtext" id="subtitle">#1<br>Time to focus!</div>
  </section>

  <h3 class="sec">Tasks</h3>
  <div class="divider"></div>

  <div id="taskList"></div>

  <div class="add-box btn" id="addTaskBtn" role="button" aria-label="Add Task">
    <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/028.png" alt="+" width="18" height="18">
    <span> Add Task</span>
  </div>

  <div class="editor" id="editor">
    <input id="taskTitle" type="text" placeholder="What are you working on?"/>
    <div class="field-title">Est Pomodoros</div>
    <div class="step">
      <div class="box" id="estBox">1</div>
      <div class="mini btn" id="upBtn" aria-label="Increase">▲</div>
      <div class="mini btn" id="downBtn" aria-label="Decrease">▼</div>
    </div>
    <div class="links">
      <span class="btn">+ Add Note</span>
      <span class="btn">+ Add Project <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/004.png" alt="lock" width="14" height="14"></span>
    </div>
    <div class="actions">
      <div class="cancel btn" id="cancelEdit">Cancel</div>
      <div class="save btn" id="saveTask">Save</div>
    </div>
  </div>

  <div class="summary" id="summary" style="display:none;">
    <span>Pomos: <strong id="pomoCount">0 / 0</strong></span>
    <span style="float:right;">Finish At: <strong id="finishAt">--:--</strong> <span id="hours">(0h)</span></span>
  </div>
</div>

<!-- Toast -->
<div class="toast" id="toast">
  <div>You've finished all your tasks for today 🎉</div>
  <div class="clear btn" id="clearTasks">Clear Tasks</div>
</div>

<script>
(function(){
  const modes = {
    pomodoro:{mins:25, subtitle:"Time to focus!", bodyClass:""},
    short:{mins:5, subtitle:"Time for a break!", bodyClass:"short"},
    long:{mins:15, subtitle:"Time for a break!", bodyClass:"long"}
  };

  // Elements
  const body = document.body;
  const tabs = document.querySelectorAll('.tab.btn');
  const timeEl = document.getElementById('time');
  const startBtn = document.getElementById('startBtn');
  const subEl = document.getElementById('subtitle');
  const addTaskBtn = document.getElementById('addTaskBtn');
  const editor = document.getElementById('editor');
  const taskTitle = document.getElementById('taskTitle');
  const estBox = document.getElementById('estBox');
  const upBtn = document.getElementById('upBtn');
  const downBtn = document.getElementById('downBtn');
  const cancelEdit = document.getElementById('cancelEdit');
  const saveTask = document.getElementById('saveTask');
  const listEl = document.getElementById('taskList');
  const summary = document.getElementById('summary');
  const pomoCount = document.getElementById('pomoCount');
  const finishAt = document.getElementById('finishAt');
  const hoursEl = document.getElementById('hours');
  const toast = document.getElementById('toast');
  const clearTasks = document.getElementById('clearTasks');
  const confetti = document.getElementById('confetti');

  // State
  let currentMode = 'pomodoro';
  let secondsLeft = modes[currentMode].mins * 60;
  let running = false;
  let interval = null;
  let tasks = []; // {id,title,est,done}
  let idSeed = 1;

  function setMode(mode){
    currentMode = mode;
    tabs.forEach(t=>t.classList.toggle('active', t.dataset.mode===mode));
    body.classList.remove('short','long');
    if(modes[mode].bodyClass) body.classList.add(modes[mode].bodyClass);
    if(!running){ // reset time only when not running
      secondsLeft = modes[mode].mins * 60;
      updateTime();
    }
    updateSubtitle();
  }

  function updateTime(){
    const m = String(Math.floor(secondsLeft/60)).padStart(2,'0');
    const s = String(secondsLeft%60).padStart(2,'0');
    timeEl.textContent = `${m}:${s}`;
  }

  function updateSubtitle(){
    const activeTask = tasks.find(t=>!t.done);
    const top = activeTask ? `#1<br>${escapeHtml(activeTask.title)}` : '#1<br>'+modes[currentMode].subtitle;
    subEl.innerHTML = top;
  }

  function startTimer(){
    if(running) return;
    running = true;
    startBtn.textContent = 'PAUSE';
    interval = setInterval(()=>{
      secondsLeft--;
      if(secondsLeft<=0){
        secondsLeft = 0;
        pauseTimer();
      }
      updateTime();
    },1000);
  }

  function pauseTimer(){
    running = false;
    startBtn.textContent = 'START';
    clearInterval(interval);
  }

  function toggleStart(){
    running ? pauseTimer() : startTimer();
  }

  function openEditor(){
    editor.classList.add('show');
    taskTitle.focus();
  }
  function closeEditor(){
    editor.classList.remove('show');
    taskTitle.value = '';
    estBox.textContent = '1';
  }

  function addTask(){
    const title = taskTitle.value.trim() || 'Untitled';
    const est = Math.max(1, parseInt(estBox.textContent,10)||1);
    tasks.push({id:idSeed++, title, est, done:false});
    renderTasks();
    closeEditor();
  }

  function renderTasks(){
    listEl.innerHTML = '';
    tasks.forEach((t, idx)=>{
      const row = document.createElement('div');
      row.className = 'task';
      row.innerHTML = `
        <div class="left">
          <span class="chk btn ${t.done?'done':''}" data-id="${t.id}" aria-label="toggle"></span>
          <div class="ttext" title="${t.title}">${escapeHtml(t.title)}</div>
        </div>
        <div class="muted">${t.done?t.est:0} / ${t.est}</div>
        <div class="kebab btn" title="menu"></div>
      `;
      listEl.appendChild(row);
    });
    summary.style.display = tasks.length? 'block':'none';
    updateCounts();
    updateSubtitle();
    toast.classList.toggle('show', tasks.length && tasks.every(t=>t.done));
  }

  function updateCounts(){
    const total = tasks.reduce((a,t)=>a+t.est,0);
    const done = tasks.reduce((a,t)=>a+(t.done?t.est:0),0);
    pomoCount.textContent = `${done} / ${total}`;
    const remaining = total - done;
    const mins = remaining * 25; // simple assumption
    hoursEl.textContent = `(${(mins/60).toFixed(1)}h)`;
    if(remaining<=0){
      finishAt.textContent = timeString(new Date());
    }else{
      const finish = new Date(Date.now() + mins*60*1000);
      finishAt.textContent = timeString(finish);
    }
  }

  function onListClick(e){
    const chk = e.target.closest('.chk');
    if(chk){
      const id = +chk.dataset.id;
      const t = tasks.find(x=>x.id===id);
      if(t){ t.done = !t.done; }
      renderTasks();
    }
  }

  function increase(){ estBox.textContent = String(Math.min(99, (parseInt(estBox.textContent,10)||1)+1)); }
  function decrease(){ estBox.textContent = String(Math.max(1, (parseInt(estBox.textContent,10)||1)-1)); }

  // Toast actions
  function clearAllTasks(){
    tasks = [];
    renderTasks();
    toast.classList.remove('show');
    launchConfetti();
  }

  // Helpers
  function timeString(d){
    const h = d.getHours();
    const m = String(d.getMinutes()).padStart(2,'0');
    return `${h}:${m}`;
  }
  function escapeHtml(s){ return s.replace(/[&<>"]/g,c=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

  // Confetti
  function launchConfetti(){
    const ctx = confetti.getContext('2d');
    const W = confetti.width = window.innerWidth;
    const H = confetti.height = window.innerHeight;
    confetti.style.display = 'block';
    const parts = Array.from({length:120}).map(()=>({
      x:Math.random()*W, y:-20-Math.random()*H/2, s:6+Math.random()*6,
      c:`hsl(${Math.random()*360},90%,60%)`, vy:2+Math.random()*3, vx:-2+Math.random()*4, rot:Math.random()*6.28
    }));
    let t=0;
    function step(){
      ctx.clearRect(0,0,W,H);
      parts.forEach(p=>{
        p.x += p.vx; p.y += p.vy; p.rot += 0.05;
        ctx.save();
        ctx.translate(p.x,p.y); ctx.rotate(p.rot);
        ctx.fillStyle=p.c;
        ctx.fillRect(-p.s/2,-p.s/2,p.s,p.s*0.7);
        ctx.restore();
      });
      t++;
      if(t<220) requestAnimationFrame(step);
      else confetti.style.display='none';
    }
    requestAnimationFrame(step);
  }

  // Wire events
  tabs.forEach(tab=>tab.addEventListener('click',()=>setMode(tab.dataset.mode)));
  startBtn.addEventListener('click', toggleStart);
  addTaskBtn.addEventListener('click', openEditor);
  cancelEdit.addEventListener('click', closeEditor);
  saveTask.addEventListener('click', addTask);
  upBtn.addEventListener('click', increase);
  downBtn.addEventListener('click', decrease);
  listEl.addEventListener('click', onListClick);
  clearTasks.addEventListener('click', clearAllTasks);

  // Init
  updateTime();
  updateSubtitle();

  // Demo helper: preload an example when user types in editor and clicks save quickly
  // (Handled by the normal flow.)

})();
</script>
</body>
</html>
